use pcb_analyze::extraction::local::developer_checkpoint::Journal;
#[test]fn every_ieee_bit_survives_a_text_checkpoint(){
 let path=std::env::temp_dir().join(format!("p7-ieee-progress-{}",std::process::id()));let _=std::fs::remove_dir_all(&path);let j=Journal::new(&path,"immutable-core".into()).unwrap();
 let values:Vec<f64>=(0..4096u64).map(|i|f64::from_bits(0x3f00000000000000+i.wrapping_mul(0x123456789ab))).chain([1333.5214321633239,1778.2794100389228,0.,-0.,1e-200,1e200]).collect();
 j.save("prepared.json",&values).unwrap();let restored:Vec<f64>=j.load("prepared.json").unwrap().unwrap();assert_eq!(values.iter().map(|v|v.to_bits()).collect::<Vec<_>>(),restored.iter().map(|v|v.to_bits()).collect::<Vec<_>>());std::fs::remove_dir_all(path).unwrap();
}
#[test]fn progress_is_identity_and_checksum_bound_and_restorable(){let path=std::env::temp_dir().join(format!("p7-progress-{}",std::process::id()));let _=std::fs::remove_dir_all(&path);let j=Journal::new(&path,"core-board-request".into()).unwrap();j.save("point-00.json",&serde_json::json!({"frequencyHz":1000.,"drive":[1.,-1.],"status":"complete"})).unwrap();let v:serde_json::Value=j.load("point-00.json").unwrap().unwrap();assert_eq!(v["status"],"complete");let wrong=Journal::new(&path,"changed-core".into()).unwrap();assert!(wrong.load::<serde_json::Value>("point-00.json").is_err());let file=path.join("point-00.json");let text=std::fs::read_to_string(&file).unwrap().replace("complete","corrupt");std::fs::write(file,text).unwrap();assert!(j.load::<serde_json::Value>("point-00.json").is_err());std::fs::remove_dir_all(path).unwrap();}
